// Family (15 cards)
export const SHANNON_FAMILY: LessonTerm[] = [
  { id: "sh-fam-1", spanish: "En España las familias se reúnen para comer los domingos. El domingo sin comer en familia es raro — es una tradición sagrada.", english: "In Spain families gather for Sunday lunch. A Sunday without a family meal is unusual — it's a sacred tradition.", category: "family", difficulty: 3, pronunciation: "ehn ehs-PAH-nyah lahs fah-MEE-lee-ahs seh reh-OO-nehn PAH-rah koh-MEHR lohs doh-MEEN-gohs...", example: "¿Por qué es tan importante la comida del domingo para las familias españolas?", level: "advanced-spain" },
  { id: "sh-fam-2", spanish: "Los abuelos españoles cuidan mucho a los nietos. En España el 40% de los abuelos cuida a los nietos mientras los padres trabajan.", english: "Spanish grandparents take great care of grandchildren. In Spain 40% of grandparents care for grandchildren while parents work.", category: "family", difficulty: 4, pronunciation: "lohs ah-BWEH-lohs ehs-pah-NYOH-lehs KWEE-dahn MOO-choh ah lohs nee-EH-tohs...", example: "¿Qué papel juegan los abuelos en la familia española?", level: "advanced-spain" },
  { id: "sh-fam-3", spanish: "En España es muy común que los hijos vivan con sus padres hasta los 30 años o más, especialmente por el elevado coste del alquiler.", english: "In Spain it's very common for children to live with their parents until age 30 or beyond, especially due to high rental costs.", category: "family", difficulty: 4, pronunciation: "ehn ehs-PAH-nyah ehs MWEE koh-MOON keh lohs EE-hohs BEE-vahn kohn soos PAH-drehs...", example: "¿Por qué muchos jóvenes españoles viven con sus padres hasta los 30?", level: "advanced-spain" },
  { id: "sh-fam-4", spanish: "El bautizo, la comunión y la confirmación son los tres grandes eventos religiosos de la vida familiar en España. Cada uno se celebra con comida y fiesta.", english: "Baptism, First Communion and Confirmation are the three major religious family events in Spain. Each is celebrated with food and a party.", category: "family", difficulty: 4, pronunciation: "ehl bow-TEE-thoh, lah koh-moo-nee-OHN ee lah kohn-feer-mah-see-OHN...", example: "¿Cuáles son los tres grandes eventos religiosos de las familias en España?", level: "advanced-spain" },
  { id: "sh-fam-5", spanish: "Los españoles son muy afectuosos. Los saludos entre amigos y familia suelen ser dos besos en la mejilla — primero la derecha, luego la izquierda.", english: "Spanish people are very affectionate. Greetings between friends and family are usually two kisses on the cheek — first the right, then the left.", category: "family", difficulty: 3, pronunciation: "lohs ehs-pah-NYOH-lehs sohn MWEE ah-fehk-too-OH-sohs...", example: "¿Cómo saludan los españoles a sus amigos y familiares?", level: "advanced-spain" },
  { id: "sh-fam-6", spanish: "El apellido en España combina el primer apellido del padre y el primer apellido de la madre. Por eso los hijos tienen dos apellidos.", english: "Spanish surnames combine the father's first surname and the mother's first surname. That's why children have two surnames.", category: "family", difficulty: 4, pronunciation: "ehl ah-peh-YEE-doh ehn ehs-PAH-nyah kohm-BEE-nah ehl pree-MEHR ah-peh-YEE-doh...", example: "¿Por qué los españoles tienen dos apellidos?", level: "advanced-spain" },
  { id: "sh-fam-7", spanish: "La paternidad y maternidad en España da derecho a 16 semanas de baja pagada al 100% para ambos progenitores desde 2021.", english: "Paternity and maternity leave in Spain gives 16 weeks of fully paid leave to both parents since 2021.", category: "family", difficulty: 5, pronunciation: "lah pah-tehr-nee-DAHD ee mah-tehr-nee-DAHD ehn ehs-PAH-nyah dah deh-REH-choh...", example: "¿Cuántas semanas de baja paternidad/maternidad se conceden en España?", level: "advanced-spain" },
  { id: "sh-fam-8", spanish: "Nuestros hijos Ila e Ian están aprendiendo español en la aplicación familiar. Christy y yo también practicamos. Es una actividad que hacemos juntos.", english: "Our children Ila and Ian are learning Spanish on the family app. Christy and I also practice. It's an activity we do together.", category: "family", difficulty: 4, pronunciation: "NWEHS-trohs EE-hohs EE-lah eh ee-AHN ehs-TAHN ah-prehn-dee-EHN-doh ehs-pah-NYOHL...", example: "¿Cómo describes la rutina de aprendizaje de español de tu familia?", level: "advanced-spain" },
  { id: "sh-fam-9", spanish: "El cuñado es el hermano de tu cónyuge. Los cuñados en España suelen ser muy cercanos — son casi como hermanos propios.", english: "Brother-in-law is your spouse's brother. Brothers-in-law in Spain are usually very close — almost like real siblings.", category: "family", difficulty: 3, pronunciation: "ehl koo-NYAH-doh ehs ehl ehr-MAH-noh deh too KOH-nyoo-heh...", example: "¿Cómo se llaman los familiares políticos en español?", level: "advanced-spain" },
  { id: "sh-fam-10", spanish: "En España decir 'eres de mi familia' a alguien que no es familia de sangre es el máximo cumplido. Significa que los consideras como tuyos.", english: "In Spain saying 'you're family to me' to someone who isn't blood family is the highest compliment. It means you consider them your own.", category: "family", difficulty: 4, pronunciation: "ehn ehs-PAH-nyah deh-THEER 'EH-rehs deh mee fah-MEE-lee-ah'...", example: "¿Qué significa para un español decirle a alguien que es 'de su familia'?", level: "advanced-spain" },
  { id: "sh-fam-11", spanish: "Chiste familiar: Un hijo pregunta: '¿Por qué te casaste con mamá, papá?' El padre responde: 'Porque me enamoré.' El hijo: '¿Y antes de eso?'", english: "Family joke: A son asks: 'Why did you marry mom, dad?' Father: 'Because I fell in love.' Son: 'And before that?'", category: "family", difficulty: 4, pronunciation: "CHEES-teh fah-mee-lee-AHR: oon EE-hoh prehn-GOO-ntah...", example: "¿Qué implica la pregunta del hijo al final del chiste?", level: "advanced-spain" },
  { id: "sh-fam-12", spanish: "En Cataluña el sistema educativo tiene tres etapas: infantil (0-6 años), primaria (6-12 años) y secundaria (12-16 años) + bachillerato opcional.", english: "In Catalonia the education system has three stages: infant (0-6), primary (6-12) and secondary (12-16) + optional baccalaureate.", category: "family", difficulty: 4, pronunciation: "ehn kah-tah-LOO-nyah ehl sees-TEH-mah eh-doo-kah-TEE-voh tee-EH-neh trehs eh-TAH-pahs...", example: "¿Cuáles son las etapas del sistema educativo en Cataluña?", level: "advanced-spain" },
  { id: "sh-fam-13", spanish: "En los colegios catalanes las clases se imparten en catalán, castellano e inglés. El catalán es la lengua vehicular principal.", english: "In Catalan schools classes are taught in Catalan, Spanish and English. Catalan is the main vehicular language.", category: "family", difficulty: 5, pronunciation: "ehn lohs koh-LEH-hee-ohs kah-tah-LAH-nehs lahs KLAH-sehs seh eem-PAHR-tehn...", example: "¿En qué idiomas se dan las clases en los colegios de Cataluña?", level: "advanced-spain" },
  { id: "sh-fam-14", spanish: "La guardería pública en Cataluña cuesta entre 200-350€ al mes. Hay ayudas del 60-80% para familias con menos de 36.000€ anuales.", english: "Public daycare in Catalonia costs €200-350/month. There are 60-80% subsidies for families earning under €36,000 per year.", category: "family", difficulty: 5, pronunciation: "lah gwahr-deh-REE-ah POO-blee-kah ehn kah-tah-LOO-nyah KWEH-stah...", example: "¿Qué ayudas existen para las guarderías en Cataluña?", level: "advanced-spain" },
  { id: "sh-fam-15", spanish: "El cole de Calella empieza a las 9h y acaba a las 17h con comedor. Los miércoles sale a las 14h. Hay actividades extraescolares hasta las 18h.", english: "Calella school starts at 9am and ends at 5pm with lunch included. Wednesdays it finishes at 2pm. After-school activities until 6pm.", category: "family", difficulty: 4, pronunciation: "ehl KOH-leh deh kah-LEHL-ah ehm-PYEH-thah ah lahs NWEH-beh...", example: "¿Cuál es el horario del colegio en Calella?", level: "advanced-spain" },
];

// School / Learning (15 cards)
export const SHANNON_SCHOOL: LessonTerm[] = [
  { id: "sh-sch-1", spanish: "Aprender una lengua como adulto requiere exposición constante. Los expertos recomiendan 90 minutos diarios para progresar de forma significativa.", english: "Learning a language as an adult requires constant exposure. Experts recommend 90 minutes daily for significant progress.", category: "school", difficulty: 4, pronunciation: "ah-prehn-DEHR oo-nah LEHN-gwah koh-moh ah-DOOL-toh reh-KWEE-reh...", example: "¿Cuánto tiempo al día recomienda practicar el español para un adulto?", level: "advanced-spain" },
  { id: "sh-sch-2", spanish: "Radio Nacional de España (RNE) tiene podcasts gratuitos en castellano estándar, perfectos para mejorar la comprensión auditiva.", english: "Radio Nacional de España (RNE) has free podcasts in standard Castilian Spanish, perfect for improving listening comprehension.", category: "school", difficulty: 4, pronunciation: "RAH-dee-oh nah-see-oh-NAHL deh ehs-PAH-nyah...", example: "¿Qué recursos gratuitos ofrece Radio Nacional de España para aprender español?", level: "advanced-spain" },
  { id: "sh-sch-3", spanish: "El Instituto Cervantes es el organismo oficial español para la enseñanza del español. Ofrece exámenes DELE reconocidos mundialmente.", english: "The Instituto Cervantes is Spain's official body for Spanish teaching. It offers internationally recognized DELE exams.", category: "school", difficulty: 4, pronunciation: "ehl eens-tee-TOO-toh thehr-VAHN-tehs ehs ehl or-GAH-nees-moh oh-fee-THEE-ahl...", example: "¿Qué es el DELE y para qué sirve?", level: "advanced-spain" },
  { id: "sh-sch-4", spanish: "Los niveles del Marco Común Europeo de Referencia para las Lenguas son: A1, A2, B1, B2, C1, C2. Shannon probablemente está en el nivel C1.", english: "The Common European Framework of Reference for Languages levels are: A1, A2, B1, B2, C1, C2. Shannon is probably at C1 level.", category: "school", difficulty: 5, pronunciation: "lohs nee-VEH-lehs dehl MAHR-koh koh-MOON eh-oo-roh-PEH-oh...", example: "¿En qué nivel del MCERL estarías según tu español actual?", level: "advanced-spain" },
  { id: "sh-sch-5", spanish: "El método de inmersión total (pensar directamente en español) es el más eficaz para avanzar de B2 a C1. Intenta soñar en español.", english: "The total immersion method (thinking directly in Spanish) is the most effective for advancing from B2 to C1. Try dreaming in Spanish.", category: "school", difficulty: 5, pronunciation: "ehl MEH-toh-doh deh een-mehr-see-OHN toh-TAHL...", example: "¿Qué es el método de inmersión total y por qué es eficaz?", level: "advanced-spain" },
  { id: "sh-sch-6", spanish: "Las telenovelas latinoamericanas ('novelas') son excelentes para aprender vocabulario cotidiano y expresiones informales del español.", english: "Latin American soap operas ('novelas') are excellent for learning everyday vocabulary and informal Spanish expressions.", category: "school", difficulty: 4, pronunciation: "lahs teh-leh-noh-VEH-lahs lah-tee-noh-ah-meh-ree-KAH-nahs...", example: "¿Por qué son útiles las telenovelas para aprender español?", level: "advanced-spain" },
  { id: "sh-sch-7", spanish: "Hablar con nativos aunque cometas errores es la forma más rápida de mejorar. Los españoles son pacientes y aprecian el esfuerzo.", english: "Talking with native speakers even when you make mistakes is the fastest way to improve. Spanish people are patient and appreciate the effort.", category: "school", difficulty: 4, pronunciation: "ah-BLAHR kohn nah-TEE-vohs AOON-keh koh-MEH-tahs eh-RROH-rehs...", example: "¿Por qué es importante hablar con nativos aunque cometas errores?", level: "advanced-spain" },
  { id: "sh-sch-8", spanish: "El español es el segundo idioma más hablado del mundo por número de hablantes nativos (después del chino mandarín). Lo hablan 500 millones de personas.", english: "Spanish is the second most spoken language in the world by native speakers (after Mandarin Chinese). 500 million people speak it.", category: "school", difficulty: 4, pronunciation: "ehl ehs-pah-NYOHL ehs ehl seh-GOON-doh ee-dee-OH-mah mahs ah-BLAH-doh...", example: "¿Cuántas personas hablan español como lengua nativa en el mundo?", level: "advanced-spain" },
  { id: "sh-sch-9", spanish: "La diferencia entre 'por' y 'para' confunde a todos los estudiantes de español. 'Por' indica causa/intercambio; 'para' indica destino/propósito.", english: "The difference between 'por' and 'para' confuses all Spanish students. 'Por' indicates cause/exchange; 'para' indicates destination/purpose.", category: "school", difficulty: 5, pronunciation: "lah dee-feh-REHN-see-ah EHN-treh 'por' ee 'PAH-rah'...", example: "¿Cuál es la diferencia principal entre 'por' y 'para' en español?", level: "advanced-spain" },
  { id: "sh-sch-10", spanish: "Los falsos amigos entre inglés y español: 'embarazada' = pregnant (no 'embarrassed'); 'éxito' = success (no 'exit'); 'sensible' = sensitive (no 'sensible').", english: "False friends between English and Spanish: 'embarazada' = pregnant (not 'embarrassed'); 'éxito' = success (not 'exit'); 'sensible' = sensitive (not 'sensible').", category: "school", difficulty: 4, pronunciation: "lohs FAHL-sohs ah-MEE-gohs EHN-treh een-GLEHS ee ehs-pah-NYOHL...", example: "¿Cuáles son los tres falsos amigos entre inglés y español más famosos?", level: "advanced-spain" },
  { id: "sh-sch-11", spanish: "Trabalenguas educativo: 'Tres tristes tigres toman trigo en un trigal. En un trigal toman trigo tres tristes tigres.' ¡Inténtalo sin parar!", english: "Educational tongue twister: 'Three sad tigers eat wheat in a wheat field. In a wheat field eat wheat three sad tigers.' Try it non-stop!", category: "school", difficulty: 5, pronunciation: "trehs TREES-tehs TEE-grehs TOH-mahn TREE-goh ehn oon tree-GAHL...", example: "¿Cuántas veces puedes decir este trabalenguas sin equivocarte?", level: "advanced-spain" },
  { id: "sh-sch-12", spanish: "Noticia educativa: El Gobierno español ha aprobado la LOMLOE, la nueva ley de educación. Uno de los cambios: el inglés ya no es obligatorio en todas las etapas.", english: "Education news: The Spanish Government has approved LOMLOE, the new education law. One change: English is no longer mandatory at all stages.", category: "school", difficulty: 5, pronunciation: "noh-TEE-see-ah eh-doo-kah-TEE-vah: ehl goh-bee-EHR-noh ehs-pah-NYOHL...", example: "¿Qué cambios introduce la LOMLOE en el sistema educativo español?", level: "advanced-spain" },
  { id: "sh-sch-13", spanish: "El sistema universitario español usa el sistema Bolonia (créditos ECTS): grado de 4 años + máster de 1-2 años + doctorado de 3-5 años.", english: "Spain's university system uses the Bologna system (ECTS credits): 4-year degree + 1-2 year master's + 3-5 year doctorate.", category: "school", difficulty: 5, pronunciation: "ehl sees-TEH-mah oo-nee-vehr-see-TAH-ree-oh ehs-pah-NYOHL OO-sah ehl sees-TEH-mah boh-LOH-nyah...", example: "¿Cómo funciona el sistema universitario español?", level: "advanced-spain" },
  { id: "sh-sch-14", spanish: "Chiste de profesor: Un alumno llega tarde a clase. El profesor: '¿Por qué llegas tarde?' El alumno: 'Me dormí.' Profesor: '¿Y no podías dormir en casa?'", english: "Teacher joke: A student arrives late to class. Teacher: 'Why are you late?' Student: 'I overslept.' Teacher: 'Couldn't you sleep at home?'", category: "school", difficulty: 3, pronunciation: "CHEES-teh deh proh-feh-SOR: oon ah-LOOM-noh YEH-gah TAHR-deh...", example: "¿Por qué es irónico el remate del chiste del profesor?", level: "advanced-spain" },
  { id: "sh-sch-15", spanish: "Escuchar música en español es una de las formas más agradables de aprender el idioma. Artistas como Rosalía, C. Tangana o Vetusta Morla son perfectos para avanzar.", english: "Listening to music in Spanish is one of the most enjoyable ways to learn the language. Artists like Rosalía, C. Tangana or Vetusta Morla are perfect for advancing.", category: "school", difficulty: 4, pronunciation: "ehs-koo-CHAHR MOO-see-kah ehn ehs-pah-NYOHL ehs oo-nah deh lahs FOR-mahs...", example: "¿Qué artistas españoles recomiendas para aprender español a través de la música?", level: "advanced-spain" },
];

// Restaurant/Dining advanced (20 cards)
export const SHANNON_RESTAURANT: LessonTerm[] = [
  { id: "sh-rest-3", spanish: "El suquet de peix es el plato marino más auténtico de la Costa Maresme. Se hace con pescado de roca, patatas y picada de almendras y azafrán.", english: "Suquet de peix is the most authentic seafood dish of Costa Maresme. It's made with rock fish, potatoes and a sauce of almonds and saffron.", category: "restaurant", difficulty: 5, pronunciation: "ehl soo-KEHT deh pehsh ehs ehl PLAH-toh mah-REE-noh mahs ow-TEHN-tee-koh...", example: "¿Qué ingredientes lleva el suquet de peix de la Costa Maresme?", level: "advanced-spain" },
  { id: "sh-rest-4", spanish: "El pa amb tomàquet (pan con tomate) es el aperitivo catalán por excelencia. Se frota pan con ajo, se unta con tomate y se riega con aceite de oliva.", english: "Pa amb tomàquet (bread with tomato) is the quintessential Catalan appetizer. Bread is rubbed with garlic, spread with tomato and drizzled with olive oil.", category: "restaurant", difficulty: 4, pronunciation: "ehl pah ahm toh-MAH-ket ehs ehl ah-peh-ree-TEE-voh kah-tah-LAHN...", example: "¿Cómo se prepara el pa amb tomàquet y cuándo se come?", level: "advanced-spain" },
  { id: "sh-rest-5", spanish: "Los cargols (caracoles en catalán) a la llauna son un plato típico de las fiestas catalanas. Se asan sobre una lata y se comen con alioli.", english: "Cargols (snails in Catalan) a la llauna are a typical dish at Catalan festivals. They're roasted on a metal sheet and eaten with aioli.", category: "restaurant", difficulty: 4, pronunciation: "lohs kahr-GOLS ah lah LYAH-oo-nah sohn oon PLAH-toh TEE-pee-koh...", example: "¿Qué son los cargols a la llauna y cuándo se comen?", level: "advanced-spain" },
  { id: "sh-rest-6", spanish: "La fideuà es como la paella pero con fideos en lugar de arroz. Es originaria de Gandía (Valencia) pero muy popular en la Costa Maresme.", english: "Fideuà is like paella but with noodles instead of rice. It originates from Gandía (Valencia) but is very popular on the Costa Maresme.", category: "restaurant", difficulty: 4, pronunciation: "lah fee-deh-OO-ah ehs KOH-moh lah pah-EH-yah PEH-roh kohn fee-DEH-ohs...", example: "¿Cuál es la diferencia entre la paella y la fideuà?", level: "advanced-spain" },
  { id: "sh-rest-7", spanish: "El vermut del mediodía es una tradición muy española. Se toma con aceitunas, anchoas y patatas bravas antes de la comida del domingo.", english: "Sunday vermouth is a very Spanish tradition. It's had with olives, anchovies and patatas bravas before Sunday lunch.", category: "restaurant", difficulty: 4, pronunciation: "ehl behr-MOOT dehl meh-dee-oh-DEE-ah ehs oo-nah trah-dee-see-OHN MWEE ehs-pah-NYOH-lah...", example: "¿Cuál es el ritual del vermut de los domingos en España?", level: "advanced-spain" },
  { id: "sh-rest-8", spanish: "En un restaurante español, el 'menú del día' siempre incluye primer plato, segundo, postre, pan y bebida. Es la mejor relación calidad-precio.", english: "In a Spanish restaurant, the 'menú del día' always includes first course, main, dessert, bread and drink. It's the best value for money.", category: "restaurant", difficulty: 3, pronunciation: "ehn oon rehs-tow-RAHN-teh ehs-pah-NYOHL, ehl meh-NOO dehl DEE-ah...", example: "¿Qué incluye siempre el menú del día en un restaurante español?", level: "advanced-spain" },
  { id: "sh-rest-9", spanish: "La crema catalana es el postre más famoso de Cataluña. Es parecida al crème brûlée pero se hace con leche, canela y cáscara de limón.", english: "Crema catalana is Catalonia's most famous dessert. It's similar to crème brûlée but made with milk, cinnamon and lemon peel.", category: "restaurant", difficulty: 4, pronunciation: "lah KREH-mah kah-tah-LAH-nah ehs ehl pos-TREH mahs fah-MOH-soh...", example: "¿En qué se diferencia la crema catalana del crème brûlée francés?", level: "advanced-spain" },
  { id: "sh-rest-10", spanish: "Noticia gastronómica: El restaurante 'Els Pescadors' de Calella lleva 3 estrellas Tripadvisor y es conocido por su arroz negro con sepia.", english: "Food news: The restaurant 'Els Pescadors' in Calella has 3 Tripadvisor stars and is known for its black rice with cuttlefish.", category: "restaurant", difficulty: 4, pronunciation: "noh-TEE-see-ah gahs-troh-NOH-mee-kah: ehl rehs-tow-RAHN-teh...", example: "¿Qué plato es la especialidad de 'Els Pescadors' de Calella?", level: "advanced-spain" },
  { id: "sh-rest-11", spanish: "El horario de las comidas en España: desayuno 7-9h, almuerzo (tentempié) 10-11h, comida 14-16h, merienda 17-18h, cena 21-22h.", english: "Meal times in Spain: breakfast 7-9am, mid-morning snack 10-11am, lunch 2-4pm, afternoon snack 5-6pm, dinner 9-10pm.", category: "restaurant", difficulty: 4, pronunciation: "ehl oh-RAH-ree-oh deh lahs koh-MEE-dahs ehn ehs-PAH-nyah...", example: "¿A qué hora cena la gente en España y por qué tan tarde?", level: "advanced-spain" },
  { id: "sh-rest-12", spanish: "El aceite de oliva virgen extra es la base de la cocina mediterránea. España es el mayor productor mundial. El de Cataluña (denominación de origen) es excelente.", english: "Extra virgin olive oil is the base of Mediterranean cuisine. Spain is the world's largest producer. Catalan olive oil (designation of origin) is excellent.", category: "restaurant", difficulty: 4, pronunciation: "ehl ah-SEH-ee-teh deh oh-LEE-vah BEER-hehn EHK-strah...", example: "¿Por qué es importante el aceite de oliva en la cocina catalana?", level: "advanced-spain" },
  { id: "sh-rest-13", spanish: "Trabalenguas culinario: 'Parra tenía una parra, y en la parra había una jarra. La jarra era de barro y la parra de Parra.' (¿Cuántas veces puedes decirlo?)", english: "Culinary tongue twister: 'Parra had a vine, and on the vine was a jar. The jar was clay and the vine was Parra's.' (How many times can you say it?)", category: "restaurant", difficulty: 5, pronunciation: "PAH-rrah teh-NEE-ah oo-nah PAH-rrah, ee ehn lah PAH-rrah ah-BEE-ah oo-nah HAH-rrah...", example: "¿Cuántas palabras parecidas hay en este trabalenguas culinario?", level: "advanced-spain" },
  { id: "sh-rest-14", spanish: "Las brasas (carbón o leña) son la forma más auténtica de asar en Cataluña. Los restaurantes con horno de leña son muy apreciados por los locales.", english: "Charcoal or wood embers are the most authentic way to grill in Catalonia. Restaurants with wood-fired ovens are highly valued by locals.", category: "restaurant", difficulty: 4, pronunciation: "lahs BRAH-sahs sohn lah FOR-mah mahs ow-TEHN-tee-kah deh ah-SAHR ehn kah-tah-LOO-nyah...", example: "¿Por qué valoran tanto los catalanes la cocina a la brasa?", level: "advanced-spain" },
  { id: "sh-rest-15", spanish: "La ensaïmada de Mallorca es el dulce más famoso de España después del turrón. Puedes encontrarla en las pastelerías de Calella los fines de semana.", english: "The ensaïmada from Mallorca is Spain's most famous pastry after turrón. You can find it in Calella's pastry shops on weekends.", category: "restaurant", difficulty: 4, pronunciation: "lah ehn-sah-ee-MAH-dah deh mah-YOR-kah ehs ehl DOOL-theh mahs fah-MOH-soh...", example: "¿Dónde puedes comprar una ensaïmada en Calella?", level: "advanced-spain" },
  { id: "sh-rest-16", spanish: "Chiste de restaurante: El camarero le trae al cliente una sopa y el cliente dice: '¡Camarero, hay una mosca en mi sopa!' El camarero: '¡No se preocupe, no va a beber mucho!'", english: "Restaurant joke: The waiter brings soup and the customer says: 'Waiter, there's a fly in my soup!' Waiter: 'Don't worry, it won't drink much!'", category: "restaurant", difficulty: 3, pronunciation: "CHEES-teh deh rehs-tow-RAHN-teh: ehl kah-mah-REH-roh leh TRAH-eh ahl KLEE-ehn-teh oo-nah SOH-pah...", example: "¿Por qué es gracioso el remate del chiste del camarero?", level: "advanced-spain" },
  { id: "sh-rest-17", spanish: "En Calella los restaurantes de mariscos frescos sirven langosta, gambas a la plancha, calamares fritos y almejas al vapor. El precio oscila entre 25-60€ por persona.", english: "In Calella, fresh seafood restaurants serve lobster, grilled prawns, fried squid and steamed clams. Price ranges €25-60 per person.", category: "restaurant", difficulty: 4, pronunciation: "ehn kah-LEHL-ah lohs rehs-tow-RAHN-tehs deh mah-REES-kohs FREHS-kohs...", example: "¿Qué mariscos puedes comer en los restaurantes de Calella y cuánto cuestan?", level: "advanced-spain" },
  { id: "sh-rest-18", spanish: "El 'guiri' es el término coloquial para el turista extranjero en España. Procede del inglés 'giri' (vuelta) y es ligeramente peyorativo.", english: "A 'guiri' is the colloquial term for foreign tourists in Spain. It comes from English 'giri' (turn) and is slightly pejorative.", category: "restaurant", difficulty: 4, pronunciation: "ehl GWEE-ree ehs ehl TEHR-mee-noh koh-loh-kwee-AHL PAH-rah ehl too-REES-tah...", example: "¿Cuándo llaman 'guiri' a los extranjeros y qué connotación tiene?", level: "advanced-spain" },
  { id: "sh-rest-19", spanish: "Para no parecer turista en un restaurante de Calella: no te sientes sin que te indiquen mesa, no llames al camarero con silbidos, y espera el postre antes de pedir la cuenta.", english: "To not seem like a tourist at a Calella restaurant: don't sit without being shown a table, don't call waiters by whistling, and wait for dessert before asking for the bill.", category: "restaurant", difficulty: 5, pronunciation: "PAH-rah noh pah-reh-THEHR too-REES-tah ehn oon rehs-tow-RAHN-teh...", example: "¿Cuáles son tres normas de etiqueta que distinguen a un local de un turista en un restaurante español?", level: "advanced-spain" },
  { id: "sh-rest-20", spanish: "El agua del grifo en Calella es potable pero tiene mucho cloro. La mayoría de locales beben agua mineral embotellada. Los filtros de agua son populares entre residentes.", english: "Tap water in Calella is drinkable but has a lot of chlorine. Most locals drink bottled mineral water. Water filters are popular among residents.", category: "restaurant", difficulty: 4, pronunciation: "ehl AH-gwah dehl GREE-foh ehn kah-LEHL-ah ehs poh-TAH-bleh...", example: "¿Es recomendable beber el agua del grifo en Calella?", level: "advanced-spain" },
];

// Dining (extra, not restaurant) (15 cards)
export const SHANNON_DINING: LessonTerm[] = [
  { id: "sh-din-1", spanish: "La escalivada es una guarnición catalana: pimientos y berenjenas asados al fuego, pelados y aderezados con aceite de oliva y ajo.", english: "Escalivada is a Catalan side dish: red peppers and aubergines roasted over fire, peeled and dressed with olive oil and garlic.", category: "dining", difficulty: 4, pronunciation: "lah ehs-kah-lee-VAH-dah ehs oo-nah gwahr-nee-see-OHN kah-tah-LAH-nah...", example: "¿Cómo se prepara la escalivada y con qué platos se sirve?", level: "advanced-spain" },
  { id: "sh-din-2", spanish: "Los calçots son cebollas tiernas que se asan al fuego en enero-febrero. Se comen con salsa romesco y es uno de los grandes rituales catalanes.", english: "Calçots are young spring onions roasted over fire in January-February. Eaten with romesco sauce, it's one of Catalonia's great rituals.", category: "dining", difficulty: 4, pronunciation: "lohs kahl-SOTZ sohn theh-BOH-yahs tee-EHR-nahs keh seh AH-sahn ahl FWEH-goh...", example: "¿Qué son los calçots y cuándo se comen?", level: "advanced-spain" },
  { id: "sh-din-3", spanish: "La romesco es la salsa catalana por excelencia: pimientos secos (ñoras), tomate, ajo, almendras, avellanas y aceite de oliva. Acompaña todo.", english: "Romesco is the quintessential Catalan sauce: dried peppers (ñoras), tomato, garlic, almonds, hazelnuts and olive oil. It goes with everything.", category: "dining", difficulty: 5, pronunciation: "lah roh-MEHS-koh ehs lah SAHL-sah kah-tah-LAH-nah por ehk-theh-LEHN-thee-ah...", example: "¿Cuáles son los ingredientes principales de la salsa romesco?", level: "advanced-spain" },
  { id: "sh-din-4", spanish: "El alioli catalán (all i oli = ajo y aceite) es una emulsión de ajo crudo y aceite de oliva. Es más intenso que la mayonesa y sin huevo.", english: "Catalan alioli (all i oli = garlic and oil) is an emulsion of raw garlic and olive oil. It's more intense than mayonnaise and egg-free.", category: "dining", difficulty: 4, pronunciation: "ehl ah-lee-OH-lee kah-tah-LAHN ehs oo-nah eh-mool-see-OHN deh AH-hoh KROO-doh...", example: "¿Cuál es la diferencia entre el alioli y la mayonesa?", level: "advanced-spain" },
  { id: "sh-din-5", spanish: "El jamón ibérico de bellota es el producto gastronómico más valorado de España. El mejor procede de Huelva y Salamanca. Cuesta 80-250€/kg.", english: "Acorn-fed Iberian ham is Spain's most prized food product. The best comes from Huelva and Salamanca. It costs €80-250/kg.", category: "dining", difficulty: 4, pronunciation: "ehl hah-MOHN ee-BEH-ree-koh deh beh-YOH-tah ehs ehl proh-DOOK-toh...", example: "¿Por qué es tan apreciado el jamón ibérico de bellota en España?", level: "advanced-spain" },
  { id: "sh-din-6", spanish: "El arroz negro catalán se hace con tinta de sepia que le da su color oscuro. Se sirve con alioli y gambas. Es muy popular en Calella.", english: "Catalan black rice is made with cuttlefish ink that gives it its dark color. Served with alioli and prawns. Very popular in Calella.", category: "dining", difficulty: 4, pronunciation: "ehl ah-RROHTH NEH-groh kah-tah-LAHN seh AH-theh kohn TEEN-tah deh SEH-pee-ah...", example: "¿Qué ingrediente le da el color negro al arroz negro catalán?", level: "advanced-spain" },
  { id: "sh-din-7", spanish: "La ceba confitada (cebolla confitada) es la guarnición más usada en Cataluña. Se cocina a fuego lento con aceite y azúcar durante 45 minutos.", english: "Caramelized onion is the most used condiment in Catalonia. Cooked slowly with oil and sugar for 45 minutes.", category: "dining", difficulty: 4, pronunciation: "lah SEH-bah kohn-fee-TAH-dah ehs lah gwahr-nee-see-OHN mahs oo-SAH-dah ehn kah-tah-LOO-nyah...", example: "¿Cómo se hace la cebolla confitada y con qué platos se usa?", level: "advanced-spain" },
  { id: "sh-din-8", spanish: "Noticia alimentaria: La Denominació d'Origen (DO) Penedès ha lanzado un nuevo cava rosado hecho con uva pinot noir. Precio: 12€.", english: "Food news: The Penedès Designation of Origin has launched a new rosé cava made with pinot noir grapes. Price: €12.", category: "dining", difficulty: 5, pronunciation: "noh-TEE-see-ah ah-lee-mehn-TAH-ree-ah: lah deh-noh-mee-nah-see-OH dee-OH-ree-hehn...", example: "¿Qué es la Denominació d'Origen Penedès y qué tipo de vino produce?", level: "advanced-spain" },
  { id: "sh-din-9", spanish: "La picada es una técnica culinaria catalana de añadir al final del guiso una mezcla molida de frutos secos, pan frito, ajo y hierbas aromáticas.", english: "La picada is a Catalan culinary technique of adding at the end of a stew a ground mix of nuts, fried bread, garlic and aromatic herbs.", category: "dining", difficulty: 5, pronunciation: "lah pee-KAH-dah ehs oo-nah TEK-nee-kah koo-lee-NAH-ree-ah kah-tah-LAH-nah...", example: "¿Qué es la picada y cuándo se añade a un guiso catalán?", level: "advanced-spain" },
  { id: "sh-din-10", spanish: "El vino catalán más internacional es el Priorat (tinto con denominación de origen). Sus bodegas están en Tarragona y exportan a 40 países.", english: "Catalonia's most international wine is Priorat (red with designation of origin). Its wineries are in Tarragona and export to 40 countries.", category: "dining", difficulty: 5, pronunciation: "ehl VEE-noh kah-tah-LAHN mahs een-tehr-nah-see-oh-NAHL ehs ehl pree-oh-RAHT...", example: "¿Por qué es tan conocido el vino Priorat fuera de España?", level: "advanced-spain" },
  { id: "sh-din-11", spanish: "En los mercados de Calella venden 'anxoves de l'Escala' (anchoas de L'Escala), consideradas las mejores anchoas del mundo. Las deben probar.", english: "At Calella's markets they sell 'anxoves de l'Escala' (anchovies from L'Escala), considered the world's best anchovies. You must try them.", category: "dining", difficulty: 4, pronunciation: "ehn lohs mehr-KAH-dohs deh kah-LEHL-ah BEHN-dehn 'ahn-SHOH-vehs deh lehs-KAH-lah'...", example: "¿Por qué son famosas las anchoas de L'Escala?", level: "advanced-spain" },
  { id: "sh-din-12", spanish: "Chiste culinario: '¿Sabe usted lo que es un filete de ternera?' 'Sí.' '¿Y un filete de cerdo?' 'Sí.' '¿Y un filete de merluza?' 'Ese... ese es de categoría aparte.'", english: "Culinary joke: 'Do you know what a veal fillet is?' 'Yes.' 'And a pork fillet?' 'Yes.' 'And a hake fillet?' 'That one... that one is a different category.'", category: "dining", difficulty: 4, pronunciation: "CHEES-teh koo-lee-NAH-ree-oh: 'SAH-beh oos-TEHD loh keh ehs oon fee-LEH-teh...", example: "¿Qué implica el chiste sobre el filete de merluza?", level: "advanced-spain" },
  { id: "sh-din-13", spanish: "La botifarra amb mongetes (butifarra con judías blancas) es el plato más representativo de la cocina doméstica catalana. Simple, nutritivo y delicioso.", english: "Botifarra amb mongetes (Catalan sausage with white beans) is the most representative dish of Catalan home cooking. Simple, nutritious and delicious.", category: "dining", difficulty: 4, pronunciation: "lah boh-tee-FAH-rrah ahm moon-HEH-tehs ehs ehl PLAH-toh mahs reh-preh-sehn-tah-TEE-voh...", example: "¿Por qué es la botifarra amb mongetes tan importante en la cocina catalana?", level: "advanced-spain" },
  { id: "sh-din-14", spanish: "El bacallà (bacalao en catalán) es el ingrediente más versátil de la cocina catalana. Se prepara en esqueixada, brandada, al pil-pil y con miel.", english: "Bacallà (cod in Catalan) is the most versatile ingredient in Catalan cooking. It's prepared as esqueixada, brandada, pil-pil style and with honey.", category: "dining", difficulty: 5, pronunciation: "ehl bah-kah-YAH ehs ehl een-greh-dee-EHN-teh mahs behr-SAH-teel...", example: "¿De cuántas maneras se puede preparar el bacallà en la cocina catalana?", level: "advanced-spain" },
  { id: "sh-din-15", spanish: "Los polvorones, el turrón de Jijona y el mazapán de Toledo son los tres dulces navideños más tradicionales de España. Se venden en todas partes en diciembre.", english: "Polvorones, Jijona nougat and Toledo marzipan are Spain's three most traditional Christmas sweets. Sold everywhere in December.", category: "dining", difficulty: 4, pronunciation: "lohs pohl-voh-ROH-nehs, ehl too-RROHN deh hee-HOH-nah ee ehl mah-thah-PAHN...", example: "¿Cuáles son los tres dulces navideños más típicos de España?", level: "advanced-spain" },
];

// Feelings (13 extra cards to reach ~15)
export const SHANNON_FEELINGS: LessonTerm[] = [
  { id: "sh-feel-3", spanish: "Estar 'en modo zombie' significa estar tan cansado que funcionas en piloto automático. 'Hoy estoy en modo zombie, necesito café urgente.'", english: "Being 'in zombie mode' means being so tired you're on autopilot. 'Today I'm in zombie mode, I need coffee urgently.'", category: "feelings", difficulty: 3, pronunciation: "ehs-TAHR 'ehn MOH-doh THOHM-bee' seeg-nee-FEE-kah ehs-TAHR tahn kahn-SAH-doh...", example: "¿Cuándo usarías la expresión 'estar en modo zombie'?", level: "advanced-spain" },
  { id: "sh-feel-4", spanish: "En España se dice 'me pone los pelos de punta' cuando algo te da miedo o asombro. Equivale a 'it gives me goosebumps' en inglés.", english: "In Spain 'me pone los pelos de punta' means something scares or astonishes you. It's equivalent to 'it gives me goosebumps' in English.", category: "feelings", difficulty: 4, pronunciation: "ehn ehs-PAH-nyah seh DEE-theh 'meh POH-neh lohs PEH-lohs deh POON-tah'...", example: "¿En qué situaciones dirías 'me pone los pelos de punta'?", level: "advanced-spain" },
  { id: "sh-feel-5", spanish: "'Flipar' significa en español quedarse alucinado o asombrado. 'Flipé en colores cuando vi el precio del piso en Calella.'", english: "'Flipar' means in Spanish to be amazed or blown away. 'I was completely blown away when I saw the apartment price in Calella.'", category: "feelings", difficulty: 4, pronunciation: "'FLEE-pahr' seeg-nee-FEE-kah ehn ehs-pah-NYOHL keh-DAHR-seh ah-loo-thee-NAH-doh...", example: "¿En qué situación usarías 'flipar' para describir tu reacción?", level: "advanced-spain" },
  { id: "sh-feel-6", spanish: "La 'morriña' gallega es la nostalgia intensa por el hogar o la tierra natal. Similar al 'saudade' portugués. Muchos emigrantes la sienten.", english: "Galician 'morriña' is intense nostalgia for home or homeland. Similar to Portuguese 'saudade'. Many emigrants feel it.", category: "feelings", difficulty: 5, pronunciation: "lah 'moh-RREE-nyah' GAH-yeh-gah ehs lah nohs-tahl-HEE-ah een-TEHN-sah...", example: "¿Qué es la 'morriña' y cuándo la sienten los españoles?", level: "advanced-spain" },
  { id: "sh-feel-7", spanish: "'Tener morro' significa tener mucha cara dura o descaro. 'Qué morro tiene ese tipo, llegó tarde y encima se queja.'", english: "'Tener morro' means to be very cheeky or brazen. 'That guy has some nerve, he arrived late and still complains.'", category: "feelings", difficulty: 4, pronunciation: "'teh-NEHR MOH-rroh' seeg-nee-FEE-kah teh-NEHR MOO-chah KAH-rah doo-RAH...", example: "¿En qué situación dirías que alguien 'tiene morro'?", level: "advanced-spain" },
  { id: "sh-feel-8", spanish: "Expresión: 'Estar hasta las narices' (o hasta el moño) significa estar completamente harto de algo. 'Estoy hasta las narices del frío en enero.'", english: "Expression: 'Estar hasta las narices' (or hasta el moño) means to be completely fed up with something. 'I'm totally fed up with the January cold.'", category: "feelings", difficulty: 4, pronunciation: "ehs-TAHR AHS-tah lahs nah-REE-thehs seeg-nee-FEE-kah ehs-TAHR kohm-pleh-tah-MEHN-teh HAHR-toh...", example: "¿Cuándo usarías 'estar hasta las narices' en una conversación?", level: "advanced-spain" },
  { id: "sh-feel-9", spanish: "'Ser un manitas' significa ser hábil con las manos, saber arreglar cosas. 'Mi vecino es un manitas: arregló el grifo, pintó el piso y montó los muebles.'", english: "'Ser un manitas' means to be handy, good at fixing things. 'My neighbor is very handy: he fixed the tap, painted the apartment and assembled the furniture.'", category: "feelings", difficulty: 4, pronunciation: "'sehr oon mah-NEE-tahs' seeg-nee-FEE-kah sehr AH-beel kohn lahs MAH-nohs...", example: "¿Eres un manitas? ¿Qué cosas sabes arreglar?", level: "advanced-spain" },
  { id: "sh-feel-10", spanish: "El duende es el concepto flamenco de la fuerza emocional artística que no se puede explicar racionalmente. Solo los grandes artistas lo poseen.", english: "Duende is the flamenco concept of emotional artistic power that can't be rationally explained. Only great artists possess it.", category: "feelings", difficulty: 5, pronunciation: "ehl DWEHN-deh ehs ehl kohn-THEHP-toh flah-MEHN-koh deh lah FWEHR-thah eh-moh-see-oh-NAHL...", example: "¿Qué es el duende en el flamenco y por qué es tan difícil de explicar?", level: "advanced-spain" },
  { id: "sh-feel-11", spanish: "'Costar un ojo de la cara' significa que algo es muy caro. 'Aparcar en el centro de Barcelona cuesta un ojo de la cara en verano.'", english: "'Costar un ojo de la cara' means something is very expensive. 'Parking in central Barcelona costs an arm and a leg in summer.'", category: "feelings", difficulty: 3, pronunciation: "'kohs-TAHR oon OH-hoh deh lah KAH-rah' seeg-nee-FEE-kah keh AHL-goh ehs MWEE KAH-roh...", example: "¿Qué cosas en España 'cuestan un ojo de la cara'?", level: "advanced-spain" },
  { id: "sh-feel-12", spanish: "Chiste: Una mujer llama al médico llorando: 'Doctor, mi marido se ha vuelto loco. Cree que es una gallina.' El médico: '¿Y por qué no lo trajo antes?' 'Por los huevos.'", english: "Joke: A woman calls the doctor crying: 'Doctor, my husband went crazy. He thinks he's a chicken.' Doctor: 'Why didn't you bring him earlier?' 'For the eggs.'", category: "feelings", difficulty: 4, pronunciation: "CHEES-teh: oo-nah moo-HER YAH-mah ahl MEH-dee-koh yoh-RAHN-doh...", example: "¿Por qué la respuesta 'por los huevos' hace gracioso el chiste?", level: "advanced-spain" },
  { id: "sh-feel-13", spanish: "'Llevarse como el perro y el gato' significa llevarse muy mal con alguien. 'Mi jefe y yo nos llevamos como el perro y el gato desde el primer día.'", english: "'Llevarse como el perro y el gato' means to get along terribly with someone. 'My boss and I have been like cats and dogs since day one.'", category: "feelings", difficulty: 4, pronunciation: "'yeh-BAHR-seh KOH-moh ehl PEH-rroh ee ehl GAH-toh'...", example: "¿Con quién te llevas como el perro y el gato? ¿Por qué?", level: "advanced-spain" },
  { id: "sh-feel-14", spanish: "Trabalenguas emocional: 'Si yo como como como y tú comes como comes, como como como como como como tú.' Explora el verbo 'comer' en todas sus formas.", english: "Emotional tongue twister: 'If I eat like I eat and you eat like you eat, I eat like you eat like I eat.' Explores the verb 'comer' in all its forms.", category: "feelings", difficulty: 5, pronunciation: "see yoh KOH-moh KOH-moh KOH-moh ee too KOH-mehs KOH-moh KOH-mehs...", example: "¿Cuántas formas del verbo 'comer' aparecen en este trabalenguas?", level: "advanced-spain" },
  { id: "sh-feel-15", spanish: "Expresión: 'No hay mal que por bien no venga.' Equivale a 'every cloud has a silver lining.' Los españoles la usan mucho para consolar a alguien.", english: "Expression: 'There's no bad that doesn't bring some good.' Equivalent to 'every cloud has a silver lining.' Spanish people use it often to comfort someone.", category: "feelings", difficulty: 4, pronunciation: "'noh AHY mahl keh por bee-EHN noh BEHN-gah'...", example: "¿En qué situaciones usarías 'no hay mal que por bien no venga'?", level: "advanced-spain" },
];

// Greetings (15 extra)
export const SHANNON_GREETINGS_EXTRA: LessonTerm[] = [
  { id: "sh-greet-6", spanish: "El saludo entre hombres en España: apretón de manos entre desconocidos, dos besos entre amigos. Nunca abrazo en primer encuentro de negocios.", english: "Male greetings in Spain: handshake with strangers, two kisses with friends. Never a hug at first business meeting.", category: "greetings", difficulty: 4, pronunciation: "ehl sah-LOO-doh EHN-treh OHM-brehs ehn ehs-PAH-nyah...", example: "¿Cómo saludan los hombres en España en contexto de negocios?", level: "advanced-spain" },
  { id: "sh-greet-7", spanish: "En Cataluña se usa 'bon dia' (buenos días), 'bona tarda' (buenas tardes) y 'bona nit' (buenas noches) en catalán. Los locales lo aprecian mucho.", english: "In Catalonia people use 'bon dia' (good morning), 'bona tarda' (good afternoon) and 'bona nit' (good night) in Catalan. Locals appreciate it greatly.", category: "greetings", difficulty: 4, pronunciation: "ehn kah-tah-LOO-nyah seh OO-sah 'bohn dee-AH', 'BOH-nah TAHR-dah'...", example: "¿Cómo dices 'buenos días', 'buenas tardes' y 'buenas noches' en catalán?", level: "advanced-spain" },
  { id: "sh-greet-8", spanish: "'¿Qué pasa, tío/tía?' es el saludo informal juvenil español. Equivale a '¿Qué hay?' o 'What's up, dude?' en inglés americano.", english: "'¿Qué pasa, tío/tía?' is the informal Spanish youth greeting. Equivalent to '¿Qué hay?' or 'What's up, dude?' in American English.", category: "greetings", difficulty: 3, pronunciation: "'keh PAH-sah, TEE-oh/TEE-ah?' ehs ehl sah-LOO-doh een-for-MAHL hoo-veh-NEEL ehs-pah-NYOHL...", example: "¿Cuándo usarías '¿Qué pasa, tío?' y cuándo sería inapropiado?", level: "advanced-spain" },
  { id: "sh-greet-9", spanish: "Despedida formal en carta o email: 'Atentamente' (Yours faithfully) o 'Un saludo cordial' (Kind regards). Evita 'Saludos' en contextos muy formales.", english: "Formal sign-offs in letters or emails: 'Atentamente' (Yours faithfully) or 'Un saludo cordial' (Kind regards). Avoid 'Saludos' in very formal contexts.", category: "greetings", difficulty: 5, pronunciation: "dehs-peh-DEE-dah for-MAHL ehn KAHR-tah oh EE-mehyl: 'ah-tehn-tah-MEHN-teh'...", example: "¿Cuál es la diferencia entre 'Atentamente' y 'Un saludo cordial' en un email?", level: "advanced-spain" },
  { id: "sh-greet-10", spanish: "Los españoles son más directos que los norteamericanos al expresar opiniones. Un 'esto no está bien' en España no significa nada personal.", english: "Spanish people are more direct than North Americans when expressing opinions. A 'this isn't right' in Spain doesn't mean anything personal.", category: "greetings", difficulty: 5, pronunciation: "lohs ehs-pah-NYOH-lehs sohn mahs dee-REHK-tohs keh lohs nor-teh-ah-meh-ree-KAH-nohs...", example: "¿Cómo percibes la comunicación directa de los españoles comparada con la cultura norteamericana?", level: "advanced-spain" },
  { id: "sh-greet-11", spanish: "En un bar de Calella, el barman te saludará con '¿Qué va a ser?' o '¿Qué le pongo?' Es la forma de preguntar qué quieres tomar.", english: "At a Calella bar, the barman will greet you with '¿Qué va a ser?' or '¿Qué le pongo?' It's how they ask what you want to drink.", category: "greetings", difficulty: 4, pronunciation: "ehn oon bahr deh kah-LEHL-ah, ehl bahr-MAHN teh sah-loo-dah-RAH kohn '¿keh vah ah sehr?'...", example: "¿Qué significa '¿Qué le pongo?' cuando el barman te lo dice?", level: "advanced-spain" },
  { id: "sh-greet-12", spanish: "Trabalenguas de saludos: 'Yo digo lo que digo, digo lo que digo yo; y digo que digo digo, y digo que digo yo.' ¡Imposible sin practicar!", english: "Greetings tongue twister: 'I say what I say, I say what I say I; and I say that I say I say, and I say that I say I.' Impossible without practice!", category: "greetings", difficulty: 5, pronunciation: "yoh DEE-goh loh keh DEE-goh, DEE-goh loh keh DEE-goh yoh...", example: "¿Cuántas veces aparece el verbo 'decir' en este trabalenguas?", level: "advanced-spain" },
  { id: "sh-greet-13", spanish: "Los pescadores de Calella se saludan con '¡Bona pesca!' (buena pesca) cuando salen al mar de madrugada. Es un deseo de buena suerte.", english: "Calella's fishermen greet each other with '¡Bona pesca!' (good fishing) when they head out to sea at dawn. It's a wish for good luck.", category: "greetings", difficulty: 3, pronunciation: "lohs pehs-kah-DOR-ehs deh kah-LEHL-ah seh sah-LOO-dahn kohn '¡BOH-nah PEHS-kah!'...", example: "¿Qué significa '¡Bona pesca!' y cuándo se usa en Calella?", level: "advanced-spain" },
  { id: "sh-greet-14", spanish: "Chiste de saludos: Dos amigos se encuentran. Uno: '¿Cómo estás?' El otro: 'Bien... aunque últimamente tengo mucho trabajo.' Uno: 'Qué bien.' Otro: '¿Qué bien que tengo trabajo?' Uno: '¿Qué querías, que te dijera qué mal?'", english: "Greeting joke: Two friends meet. One: 'How are you?' Other: 'Good... though lately I have a lot of work.' One: 'How nice.' Other: 'How nice that I have work?' One: 'What, you wanted me to say how awful?'", category: "greetings", difficulty: 4, pronunciation: "CHEES-teh deh sah-LOO-dohs: dohs ah-MEE-gohs seh ehn-KWEHN-trahn...", example: "¿Qué comentario social hace este chiste sobre las conversaciones cotidianas?", level: "advanced-spain" },
  { id: "sh-greet-15", spanish: "Al entrar en una tienda en España es costumbre decir 'Buenos días' o 'Buenas'. Al salir, 'Hasta luego'. Ignorar este ritual parece maleducado.", english: "When entering a shop in Spain it's custom to say 'Good morning' or 'Buenas'. When leaving, 'Goodbye'. Ignoring this ritual seems rude.", category: "greetings", difficulty: 3, pronunciation: "ahl ehn-TRAHR ehn oo-nah tee-EHN-dah ehn ehs-PAH-nyah ehs kohs-TOOM-breh deh-THEER...", example: "¿Por qué es importante saludar al entrar en tiendas pequeñas en España?", level: "advanced-spain" },
  { id: "sh-greet-16", spanish: "'Oye' se usa en España para llamar la atención de alguien de forma informal. 'Oye, ¿tienes un momento?' es más suave que 'Escucha'.", english: "'Oye' is used in Spain to informally get someone's attention. 'Oye, do you have a moment?' is softer than 'Escucha' (Listen).", category: "greetings", difficulty: 3, pronunciation: "'OH-yeh' seh OO-sah ehn ehs-PAH-nyah PAH-rah yah-MAHR lah ah-tehn-see-OHN...", example: "¿Cuál es la diferencia entre 'oye', 'escucha' y 'mira' para llamar la atención?", level: "advanced-spain" },
  { id: "sh-greet-17", spanish: "La despedida en Cataluña: 'Adéu' (adiós en catalán) o 'Fins aviat' (hasta pronto). Muy distinto del castizo 'Hasta luego' madrileño.", english: "Saying goodbye in Catalonia: 'Adéu' (goodbye in Catalan) or 'Fins aviat' (see you soon). Very different from the Madrid 'Hasta luego'.", category: "greetings", difficulty: 4, pronunciation: "lah dehs-peh-DEE-dah ehn kah-tah-LOO-nyah: 'ah-DEH-oo' oh 'feens ah-bee-AHT'...", example: "¿Cómo te despides en catalán?", level: "advanced-spain" },
  { id: "sh-greet-18", spanish: "Noticia social: Según un estudio de 2024, los españoles son los europeos que más tiempo pasan hablando con vecinos y amigos en la calle.", english: "Social news: According to a 2024 study, Spanish people spend the most time of all Europeans talking with neighbors and friends in the street.", category: "greetings", difficulty: 4, pronunciation: "noh-TEE-see-ah soh-THEE-ahl: seh-GOON oon ehs-TOO-dee-oh...", example: "¿Por qué crees que los españoles pasan más tiempo hablando en la calle que otros europeos?", level: "advanced-spain" },
  { id: "sh-greet-19", spanish: "Los vecinos de Calella se conocen mucho mejor que en las ciudades grandes. Si te mudas allí, en 6 meses conocerás a casi todo el barrio.", english: "Calella's neighbors know each other much better than in big cities. If you move there, in 6 months you'll know almost your entire neighborhood.", category: "greetings", difficulty: 4, pronunciation: "lohs beh-THEE-nohs deh kah-LEHL-ah seh koh-NOH-thehn MOO-choh meh-HOR...", example: "¿Cómo es la vida comunitaria en Calella comparada con una gran ciudad?", level: "advanced-spain" },
  { id: "sh-greet-20", spanish: "Expresión del pescador local: 'Avui fa tramuntana, no sortim' (Hoy hay tramontana, no salimos). Es una frase que define el ritmo de vida en Calella.", english: "Local fisherman's expression: 'Today there's a north wind, we're not going out.' It's a phrase that defines the pace of life in Calella.", category: "greetings", difficulty: 4, pronunciation: "ah-BOO-ee fah trah-moon-TAH-nah, noh sohr-TEEM...", example: "¿Qué dice esta frase sobre la relación de los pescadores de Calella con el clima?", level: "advanced-spain" },
];

// Polite phrases extra (18 more to reach ~20)
export const SHANNON_POLITE_EXTRA: LessonTerm[] = [
  { id: "sh-pol-3", spanish: "'No hay de qué' y 'de nada' son las dos formas más comunes de responder a 'gracias' en España. 'No hay de qué' es más formal y elaborado.", english: "'No hay de qué' and 'de nada' are the two most common ways to respond to 'gracias' in Spain. 'No hay de qué' is more formal and elaborate.", category: "polite", difficulty: 3, pronunciation: "'noh AHY deh keh' ee 'deh NAH-dah' sohn lahs dohs FOR-mahs mahs koh-MOO-nehs...", example: "¿Cuándo usarías 'no hay de qué' en lugar de 'de nada'?", level: "advanced-spain" },
  { id: "sh-pol-4", spanish: "'¿Me concede un momento de su tiempo?' es la forma más educada de pedir atención en un contexto formal o con personas mayores.", english: "'Would you grant me a moment of your time?' is the most polite way to ask for attention in formal contexts or with elders.", category: "polite", difficulty: 5, pronunciation: "'meh kohn-THEH-deh oon moh-MEHN-toh deh soo TYEHM-poh?'...", example: "¿En qué situación usarías esta forma tan formal de pedir atención?", level: "advanced-spain" },
  { id: "sh-pol-5", spanish: "En España se usa 'usted' con el médico, el juez, personas mayores y en contextos formales. Con colegas de trabajo, aunque sean mayores, se tutea.", english: "In Spain 'usted' is used with doctors, judges, elderly people and in formal contexts. With work colleagues, even older ones, you use 'tú'.", category: "polite", difficulty: 4, pronunciation: "ehn ehs-PAH-nyah seh OO-sah 'oos-TEHD' kohn ehl MEH-dee-koh, ehl HWETH...", example: "¿Con quién usarías 'usted' y con quién 'tú' en España?", level: "advanced-spain" },
  { id: "sh-pol-6", spanish: "'Por si acaso' significa 'just in case'. 'Llevo el paraguas por si acaso llueve' = I'm bringing the umbrella just in case it rains.", english: "'Por si acaso' means 'just in case'. 'Llevo el paraguas por si acaso llueve' = I'm bringing the umbrella just in case it rains.", category: "polite", difficulty: 3, pronunciation: "'por see ah-KAH-soh' seeg-nee-FEE-kah 'just in case'...", example: "Pon 'por si acaso' en una frase sobre vivir en Calella.", level: "advanced-spain" },
  { id: "sh-pol-7", spanish: "'A ver' es una muletilla española muy frecuente. Puede significar 'let's see', 'come on' o simplemente ser un relleno verbal.", english: "'A ver' is a very frequent Spanish filler. It can mean 'let's see', 'come on' or simply be a verbal filler.", category: "polite", difficulty: 3, pronunciation: "'ah BEHR' ehs oo-nah moo-leh-TEE-yah ehs-pah-NYOH-lah MWEE freh-KWEHN-teh...", example: "¿En cuántos contextos diferentes puedes usar 'a ver'?", level: "advanced-spain" },
  { id: "sh-pol-8", spanish: "En España interrumpir en una conversación no es necesariamente maleducado — a veces es una señal de entusiasmo y participación activa.", english: "In Spain interrupting in conversation isn't necessarily rude — sometimes it's a sign of enthusiasm and active participation.", category: "polite", difficulty: 5, pronunciation: "ehn ehs-PAH-nyah een-teh-rroo-MEER ehn oo-nah kohn-behr-sah-see-OHN noh ehs neh-theh-SAH-ree-ah-MEHN-teh mah-leh-doo-KAH-doh...", example: "¿Por qué interrumpir no siempre es maleducado en España?", level: "advanced-spain" },
  { id: "sh-pol-9", spanish: "'Hombre' (y 'mujer') se usan como interjecciones en España para expresar sorpresa, enfatizar o suavizar algo. '¡Hombre, no te pongas así!'", english: "'Hombre' (and 'mujer') are used as interjections in Spain to express surprise, emphasize or soften something. 'Come on, don't get like that!'", category: "polite", difficulty: 4, pronunciation: "'OHM-breh' ee 'moo-HER' seh OO-sahn KOH-moh een-tehr-HEHk-see-OH-nehs...", example: "¿Cuándo usarías 'hombre' como interjección en español?", level: "advanced-spain" },
  { id: "sh-pol-10", spanish: "'Con mucho gusto' es la respuesta más elegante a una petición. Equivale a 'With pleasure' en inglés. Mucho más sofisticado que 'sí, claro'.", english: "'Con mucho gusto' is the most elegant response to a request. Equivalent to 'With pleasure' in English. Much more sophisticated than 'sí, claro'.", category: "polite", difficulty: 4, pronunciation: "'kohn MOO-choh GOOS-toh' ehs lah rehs-PWEH-stah mahs eh-leh-GAHN-teh...", example: "¿En qué situaciones usarías 'con mucho gusto' en lugar de 'sí, claro'?", level: "advanced-spain" },
  { id: "sh-pol-11", spanish: "Los españoles tienen fama de ser ruidosos. De hecho, los bares y restaurantes en España son 30% más ruidosos que en el norte de Europa.", english: "Spanish people are famous for being loud. In fact, bars and restaurants in Spain are 30% louder than in northern Europe.", category: "polite", difficulty: 4, pronunciation: "lohs ehs-pah-NYOH-lehs tee-EH-nehn FAH-mah deh sehr RWEE-doh-sohs...", example: "¿Por qué son tan ruidosos los ambientes sociales en España?", level: "advanced-spain" },
  { id: "sh-pol-12", spanish: "Trabalenguas de cortesía: 'María Chucena techaba su choza cuando un leñador que por allí pasaba le dijo: María Chucena, ¿techás tu choza o la choza ajena?'", english: "Politeness tongue twister: 'María Chucena was thatching her hut when a woodcutter passing by said: María Chucena, are you thatching your hut or someone else's?'", category: "polite", difficulty: 5, pronunciation: "mah-REE-ah choo-THEH-nah teh-CHAH-bah soo CHOH-thah KWAHN-doh...", example: "¿Cuál es la pregunta final del trabalenguas y por qué es confusa?", level: "advanced-spain" },
  { id: "sh-pol-13", spanish: "En los negocios españoles, las reuniones suelen empezar 10-15 minutos tarde. Es la norma cultural. Llegar exactamente a la hora puede parecer impaciente.", english: "In Spanish business, meetings usually start 10-15 minutes late. It's the cultural norm. Arriving exactly on time can seem impatient.", category: "polite", difficulty: 5, pronunciation: "ehn lohs neh-GOH-see-ohs ehs-pah-NYOH-lehs, lahs reh-oo-nee-OH-nehs SWEH-lehn ehm-peh-THAHR...", example: "¿Cuánto tiempo de retraso es aceptable en una reunión de negocios en España?", level: "advanced-spain" },
  { id: "sh-pol-14", spanish: "Chiste de educación: '¿Cómo se dice 'por favor' en inglés?' 'Please.' '¡Por favor, dilo más fuerte!' '¡PLEASE!' '¡Muy bien, pero aún falta el 'thank you'!'", english: "Education joke: 'How do you say 'por favor' in English?' 'Please.' 'Please, say it louder!' 'PLEASE!' 'Very good, but you're still missing the 'thank you'!'", category: "polite", difficulty: 3, pronunciation: "CHEES-teh deh eh-doo-kah-see-OHN: '¿KOH-moh seh DEE-theh por fah-BOR ehn een-GLEHS?'...", example: "¿Qué confusión lingüística explota este chiste?", level: "advanced-spain" },
  { id: "sh-pol-15", spanish: "Noticia de cortesía: Un estudio revela que los madrileños dicen 'por favor' un 40% menos que los barceloneses y un 60% menos que los valencianos.", english: "Politeness news: A study reveals that people from Madrid say 'please' 40% less than those from Barcelona and 60% less than those from Valencia.", category: "polite", difficulty: 5, pronunciation: "noh-TEE-see-ah deh kor-teh-SEE-ah: oon ehs-TOO-dee-oh reh-VEH-lah...", example: "¿Por qué crees que hay diferencias regionales en el uso de 'por favor' en España?", level: "advanced-spain" },
  { id: "sh-pol-16", spanish: "'¡Ojo!' es una advertencia española que significa 'careful!' o 'watch out!' No tiene nada que ver con el ojo como órgano visual en este contexto.", english: "'¡Ojo!' is a Spanish warning meaning 'careful!' or 'watch out!' It has nothing to do with the eye as a visual organ in this context.", category: "polite", difficulty: 3, pronunciation: "'OH-hoh!' ehs oo-nah ahd-behr-TEHN-see-ah ehs-pah-NYOH-lah...", example: "¿En qué situaciones de peligro o aviso usarías '¡Ojo!'?", level: "advanced-spain" },
  { id: "sh-pol-17", spanish: "El piropo es un comentario (a veces subido de tono) que los españoles hacen a alguien que les parece atractivo. Culturalmente complejo — algunos lo ven como halago, otros como acoso.", english: "A piropo is a comment (sometimes risqué) that Spanish people make to someone they find attractive. Culturally complex — some see it as flattery, others as harassment.", category: "polite", difficulty: 5, pronunciation: "ehl pee-ROH-poh ehs oon koh-mehn-TAH-ree-oh keh lohs ehs-pah-NYOH-lehs AH-thehn ah AHL-gyehn...", example: "¿Cómo ha cambiado la percepción del piropo en la sociedad española actual?", level: "advanced-spain" },
  { id: "sh-pol-18", spanish: "'Molarme' o 'molar' significa gustar en argot español. 'Me mola mucho ese restaurante del puerto de Calella' = 'I really like that harbor restaurant.'", english: "'Molarme' or 'molar' means to like something in Spanish slang. 'Me mola mucho ese restaurante del puerto de Calella' = 'I really like that harbor restaurant.'", category: "polite", difficulty: 4, pronunciation: "'moh-LAHR-meh' oh 'moh-LAHR' seeg-nee-FEE-kah goos-TAHR ehn ahr-GOT ehs-pah-NYOHL...", example: "¿Qué cosas de Calella te 'molan' más?", level: "advanced-spain" },
  { id: "sh-pol-19", spanish: "'Tío' y 'tía' como apelativo entre amigos (no familia) es el argot español más universal entre jóvenes. 'Tío, qué buena la playa hoy'.", english: "'Tío' and 'tía' as a term of address between friends (not family) is the most universal Spanish slang among young people. 'Dude, the beach is great today'.", category: "polite", difficulty: 3, pronunciation: "'TEE-oh' ee 'TEE-ah' KOH-moh ah-peh-lah-TEE-voh EHN-treh ah-MEE-gohs...", example: "¿Cuándo es apropiado usar 'tío/tía' y cuándo no?", level: "advanced-spain" },
  { id: "sh-pol-20", spanish: "Expresión avanzada: 'Ni en broma' significa 'no way' o 'absolutely not'. 'Ni en broma voy a pagar 800 euros de alquiler por ese estudio.'", english: "Advanced expression: 'Ni en broma' means 'no way' or 'absolutely not'. 'No way am I paying €800 rent for that studio.'", category: "polite", difficulty: 4, pronunciation: "'nee ehn BROH-mah' seeg-nee-FEE-kah 'no way' oh 'absolutely not'...", example: "¿En qué situaciones usarías 'ni en broma'?", level: "advanced-spain" },
];
